	@Test
	void concurrentCallsForOneOwnerShareTheInProgressIdentityReservation() throws Exception {
		CountDownLatch firstIdentityEntered = new CountDownLatch(1);
		CountDownLatch releaseFirstIdentity = new CountDownLatch(1);
		AtomicInteger identities = new AtomicInteger();
		ClosingValueStore values = new ClosingValueStore(directory, config()) {
			@Override
			CleanupReservation reserveCleanupIdentity(boolean mayWait) throws IOException {
				if (identities.incrementAndGet() == 1) {
					firstIdentityEntered.countDown();
					await(releaseFirstIdentity);
				}
				return super.reserveCleanupIdentity(mayWait);
			}
		};
		try (Fixture fixture = new Fixture(directory, config(), collecting(new ArrayList<>()), values)) {
			Object owner = new Object();
			CountDownLatch coalescedWait = new CountDownLatch(1);
			fixture.cleanup.admissionWaitStartedForTest(coalescedWait::countDown);
			AtomicReference<Throwable> failure = new AtomicReference<>();
			AtomicReference<Set<Long>> firstCandidates = new AtomicReference<>();
			AtomicReference<Set<Long>> secondCandidates = new AtomicReference<>();
			Thread first = Thread.ofPlatform()
					.start(() -> admitCapturing(fixture.cleanup, owner, firstCandidates, failure));
			Thread second = null;
			try {
				assertTrue(firstIdentityEntered.await(10, TimeUnit.SECONDS));
				second = Thread.ofPlatform()
						.start(() -> admitCapturing(fixture.cleanup, owner, secondCandidates, failure));
				assertTrue(coalescedWait.await(1, TimeUnit.SECONDS),
						"a second caller for the same owner must wait for the existing initializer");
				assertEquals(1, fixture.cleanup.metrics().activeProducers());
			} finally {
				releaseFirstIdentity.countDown();
				first.join(10_000L);
				if (second != null) {
					second.join(10_000L);
				}
			}
			assertEquals(null, failure.get());
			assertSame(firstCandidates.get(), secondCandidates.get());
			assertEquals(1, identities.get());
			fixture.cleanup.complete(owner);
			assertTrue(fixture.cleanup.awaitEmpty(10, TimeUnit.SECONDS));
		}
	}

	private static void admitCapturing(AsyncValueRetirementCoordinator cleanup, Object owner,
			AtomicReference<Set<Long>> result, AtomicReference<Throwable> failure) {
		try {
			cleanup.admit(owner, true);
			result.set(cleanup.candidates(owner));
		} catch (Throwable caught) {
			failure.compareAndSet(null, caught);
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void failedProcessingOrAcknowledgmentReplaysTheSameBatch(boolean afterCommit) throws Exception {
		AtomicInteger attempts = new AtomicInteger();
		List<long[]> seen = new CopyOnWriteArrayList<>();
		CountDownLatch retryEntered = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		try (Fixture fixture = new Fixture(directory, config(), processor((ids, size) -> {
			seen.add(Arrays.copyOf(ids, size));
			int attempt = attempts.incrementAndGet();
			if (attempt == 1 && !afterCommit) {
				throw new IOException("Injected maintenance abort");
			}
			if (attempt == 2) {
				retryEntered.countDown();
				await(release);
			}
			return true;
		}))) {
			AtomicBoolean firstCommit = new AtomicBoolean(true);
			if (afterCommit) {
				fixture.cleanup.afterBatchCommitForTest(() -> {
					if (firstCommit.getAndSet(false)) {
						throw new SailException("Injected failure after commit, before acknowledgment");
					}
				});
			}
			publish(fixture.cleanup, 1, 3);
			fixture.cleanup.start();
			try {
				assertTrue(retryEntered.await(10, TimeUnit.SECONDS));
				assertEquals(0L, fixture.cleanup.metrics().acknowledgedCandidates());
				assertEquals(3L, fixture.cleanup.metrics().unacknowledgedCandidates());
				assertEquals(1L, fixture.cleanup.metrics().failedBatches());
				assertArrayEquals(seen.get(0), seen.get(1));
			} finally {
				release.countDown();
			}
			assertTrue(fixture.cleanup.awaitEmpty(10, TimeUnit.SECONDS));
			assertEquals(3L, fixture.cleanup.metrics().acknowledgedCandidates());
		}
	}

	@Test
	void shutdownWakesWaitingProducerAndRetainsTheActiveNativeWorker() throws Exception {
		CountDownLatch nativeEntered = new CountDownLatch(1);
		CountDownLatch releaseNative = new CountDownLatch(1);
		AtomicReference<ClosingValueStore> nativeValues = new AtomicReference<>();
		LmdbStoreConfig config = smallestConfig().setAsyncValueCleanupShutdownTimeoutMillis(25L);
		try (Fixture fixture = new Fixture(directory, config, processor((ids, size) -> {
			ValueStore values = nativeValues.get();
			values.startTransaction(true);
			try {
				nativeEntered.countDown();
				await(releaseNative);
				return false;
			} finally {
				values.rollback();
			}
		}))) {
			nativeValues.set(fixture.values);
			publish(fixture.cleanup, 1, 1);
			fixture.cleanup.start();
			assertTrue(nativeEntered.await(10, TimeUnit.SECONDS));
			CountDownLatch producerWaiting = new CountDownLatch(1);
			fixture.cleanup.admissionWaitStartedForTest(producerWaiting::countDown);
			AtomicReference<Throwable> failure = new AtomicReference<>();
			Thread producer = Thread.ofPlatform().start(() -> {
				try {
					fixture.cleanup.admit(new Object(), true);
				} catch (Throwable caught) {
					failure.set(caught);
				}
			});
			try {
				assertTrue(producerWaiting.await(10, TimeUnit.SECONDS));
				SailException blocked = assertThrows(SailException.class, fixture.cleanup::stopAndAwait);
				assertTrue(blocked.getMessage().contains("LMDB remains open and owned"));
				producer.join(10_000L);
				assertFalse(producer.isAlive());
				assertInstanceOf(SailException.class, failure.get());
				assertTrue(failure.get().getMessage().contains("shutting down"));
				assertTrue(fixture.values.cleanupTransactionId() >= 0L,
						"the environment is still native-open while the worker owns its transaction");
			} finally {
				releaseNative.countDown();
			}
			fixture.cleanup.stopAndAwait();
		}
	}

