	@ParameterizedTest
	@ValueSource(strings = { "manifest-checksum", "manifest-partial", "manifest-count", "stream-partial",
			"stream-checksum" })
	void partialOrCorruptSpoolNeverAuthorizesARecord(String corruption) throws Exception {
		writeSpool(1, 3);
		Path manifest = manifest(directory);
		if (corruption.startsWith("manifest")) {
			byte[] bytes = Files.readAllBytes(manifest);
			if (corruption.equals("manifest-checksum")) {
				bytes[bytes.length - 1] ^= 1;
			} else if (corruption.equals("manifest-count")) {
				ByteBuffer.wrap(bytes).putInt(36, Integer.MAX_VALUE);
				writeManifestChecksum(bytes);
			} else {
				bytes = Arrays.copyOf(bytes, bytes.length - 3);
			}
			Files.write(manifest, bytes);
		} else {
			Path stream = streamFiles(directory).get(0);
			if (corruption.equals("stream-partial")) {
				try (FileChannel channel = FileChannel.open(stream, StandardOpenOption.WRITE)) {
					channel.truncate(7L);
				}
			} else {
				byte[] bytes = Files.readAllBytes(stream);
				bytes[bytes.length - 1] ^= 1;
				Files.write(stream, bytes);
			}
		}
		List<Long> processed = new CopyOnWriteArrayList<>();
		try (Fixture reopened = new Fixture(directory, smallestConfig(), collecting(processed))) {
			assertEquals(0, reopened.cleanup.metrics().activeProducers());
			reopened.cleanup.start();
			assertTrue(reopened.cleanup.awaitEmpty(10, TimeUnit.SECONDS));
			assertTrue(processed.isEmpty());
			assertFalse(Files.exists(manifest));
			assertTrue(streamFiles(directory).isEmpty());
		}
	}

