	@Test
	void durableContinuationsGetTurnsWhileARootStreamRemainsNonempty() throws Exception {
		AtomicInteger consecutiveRoots = new AtomicInteger();
		AtomicInteger maximumRoots = new AtomicInteger();
		AtomicInteger completedRoots = new AtomicInteger();
		AtomicInteger intermediateLegacyPasses = new AtomicInteger();
		AsyncValueRetirementCoordinator.Processor processor = new AsyncValueRetirementCoordinator.Processor() {
			@Override
			public boolean process(long[] ids, int size, ValueStore.CleanupReservation guard) {
				maximumRoots.accumulateAndGet(consecutiveRoots.incrementAndGet(), Math::max);
				completedRoots.addAndGet(size);
				return true;
			}

			@Override
			public boolean idle() {
				if (completedRoots.get() > 0 && completedRoots.get() < 100) {
					intermediateLegacyPasses.incrementAndGet();
				}
				consecutiveRoots.set(0);
				return false;
			}
		};
		try (Fixture fixture = new Fixture(directory, config(), processor)) {
			publish(fixture.cleanup, 1, 100);
			fixture.cleanup.start();
			assertTrue(fixture.cleanup.awaitEmpty(10, TimeUnit.SECONDS));
			assertEquals(100, completedRoots.get());
			assertTrue(intermediateLegacyPasses.get() >= 3);
			assertTrue(maximumRoots.get() <= 8, "legacy work cannot starve behind an unbounded disk stream");
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void failedRootAndIdleWorkBothWaitBeforeRetry(boolean idleOnly) throws Exception {
		AtomicInteger attempts = new AtomicInteger();
		AtomicLong firstAttempt = new AtomicLong();
		AtomicLong interval = new AtomicLong();
		CountDownLatch waiting = new CountDownLatch(1);
		CountDownLatch secondEntered = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		BatchProcessor attempt = (ids, size) -> {
			if (attempts.incrementAndGet() == 1) {
				firstAttempt.set(System.nanoTime());
			} else {
				interval.compareAndSet(0L, System.nanoTime() - firstAttempt.get());
				secondEntered.countDown();
				await(release);
			}
			return idleOnly;
		};
		AsyncValueRetirementCoordinator.Processor processor = new AsyncValueRetirementCoordinator.Processor() {
			@Override
			public boolean process(long[] ids, int size, ValueStore.CleanupReservation guard) throws IOException {
				return attempt.process(ids, size);
			}

			@Override
			public boolean idle() throws IOException {
				return idleOnly && attempt.process(null, 0);
			}
		};
		try (Fixture fixture = new Fixture(directory, config(), processor)) {
			if (!idleOnly) {
				publish(fixture.cleanup, 1, 1);
			}
			fixture.cleanup.retryWaitStartedForTest(waiting::countDown);
			fixture.cleanup.start();
			try {
				assertTrue(waiting.await(10, TimeUnit.SECONDS));
				for (int i = 0; i < 16; i++) {
					fixture.cleanup.signal();
				}
				assertTrue(secondEntered.await(10, TimeUnit.SECONDS));
				assertTrue(interval.get() >= TimeUnit.MILLISECONDS.toNanos(8L),
						"notifications must not collapse the bounded retry cadence: " + interval.get());
			} finally {
				release.countDown();
			}
		}
	}

	private void writeSpool(int start, int count) throws Exception {
		try (Fixture fixture = new Fixture(directory, config(), collecting(new ArrayList<>()))) {
			publish(fixture.cleanup, start, count);
			fixture.closeWithSpool();
		}
	}

	private static void publish(AsyncValueRetirementCoordinator cleanup, int start, int count) throws IOException {
		Object owner = new Object();
		cleanup.admit(owner, true);
		Set<Long> candidates = cleanup.candidates(owner);
		for (int i = 0; i < count; i++) {
			candidates.add(candidate(start + i));
		}
		cleanup.recordBeforePublication(candidates, 0L);
		cleanup.published(owner);
		cleanup.complete(owner);
	}

	private static void assertBounds(AsyncValueRetirementCoordinator cleanup, int candidates, long bytes) {
		AsyncValueRetirementCoordinator.Metrics metrics = cleanup.metrics();
		assertTrue(metrics.pendingCandidates() <= candidates, metrics.toString());
		assertTrue(metrics.highWaterCandidates() <= candidates, metrics.toString());
		assertTrue(metrics.retainedBytes() <= bytes, metrics.toString());
		assertTrue(metrics.highWaterBytes() <= bytes, metrics.toString());
	}

	private static List<Long> range(int start, int count) {
		List<Long> result = new ArrayList<>(count);
		for (int i = 0; i < count; i++) {
			result.add(candidate(start + i));
		}
		return result;
	}

	private static long candidate(long ordinal) {
		return ValueIds.createId(ValueIds.T_BNODE, ordinal);
	}

	private static LmdbStoreConfig config() {
		return new LmdbStoreConfig().setAsyncValueCleanup(true)
				.setValueDBSize(16L * 1024 * 1024)
				.setValueOverlayEnabled(false)
				.setAsyncValueCleanupBatchSize(4)
				.setAsyncValueCleanupMaxCandidates(128)
				.setAsyncValueCleanupMaxBytes(16 * 1024)
				.setAsyncValueCleanupMaxPendingProducers(4)
				.setAsyncValueCleanupAdmissionTimeoutMillis(10_000L);
	}

	private static LmdbStoreConfig smallestConfig() {
		return config().setAsyncValueCleanupMaxCandidates(16)
				.setAsyncValueCleanupMaxBytes(4096)
				.setAsyncValueCleanupBatchSize(1)
				.setAsyncValueCleanupMaxPendingProducers(1);
	}

	@FunctionalInterface
	private interface BatchProcessor {
		boolean process(long[] ids, int size) throws IOException;
	}

	private static AsyncValueRetirementCoordinator.Processor collecting(List<Long> output) {
		return processor((ids, size) -> {
			for (int i = 0; i < size; i++) {
				output.add(ids[i]);
			}
			return true;
		});
	}

	private static AsyncValueRetirementCoordinator.Processor processor(BatchProcessor process) {
		return new AsyncValueRetirementCoordinator.Processor() {
			@Override
			public boolean process(long[] ids, int size, ValueStore.CleanupReservation guard) throws IOException {
				return process.process(ids, size);
			}

			@Override
			public boolean idle() {
				return false;
			}
		};
	}

	private static void await(CountDownLatch latch) throws IOException {
		try {
			if (!latch.await(10, TimeUnit.SECONDS)) {
				throw new IOException("Test latch was not released");
			}
		} catch (InterruptedException interrupted) {
			Thread.currentThread().interrupt();
			throw new IOException(interrupted);
		}
	}

	private static void awaitUnchecked(CountDownLatch latch) {
		try {
			await(latch);
		} catch (IOException failure) {
			throw new UncheckedIOException(failure);
		}
	}

	private static Path cleanupDirectory(Path directory) {
		return directory.resolve("async-value-cleanup");
	}

	private static Path manifest(Path directory) {
		return cleanupDirectory(directory).resolve("pending.rgc");
	}

	private static List<Path> streamFiles(Path directory) throws IOException {
		try (var files = Files.list(cleanupDirectory(directory))) {
			return files.filter(path -> path.getFileName().toString().endsWith(".ids")).toList();
		}
	}

	private static void writeManifestChecksum(byte[] bytes) {
		CRC32C checksum = new CRC32C();
		checksum.update(bytes, 0, bytes.length - Integer.BYTES);
		ByteBuffer.wrap(bytes).putInt(bytes.length - Integer.BYTES, (int) checksum.getValue());
	}

	private static final class Fixture implements AutoCloseable {
		final ClosingValueStore values;
		final AsyncValueRetirementCoordinator cleanup;
		private boolean closed;

		Fixture(Path directory, LmdbStoreConfig config, AsyncValueRetirementCoordinator.Processor processor)
				throws IOException {
			this(directory, config, processor, new ClosingValueStore(directory, config));
		}

		Fixture(Path directory, LmdbStoreConfig config, AsyncValueRetirementCoordinator.Processor processor,
				ClosingValueStore values) throws IOException {
			this.values = values;
			cleanup = new AsyncValueRetirementCoordinator(directory, config, values, processor);
		}

		void closeWithSpool() throws IOException {
			close(true);
		}

		@Override
		public void close() throws IOException {
			close(false);
		}

		private void close(boolean spool) throws IOException {
			if (!closed) {
				cleanup.stopAndAwait();
				cleanup.prepareSpool();
				if (spool && cleanup.hasPreparedSpool()) {
					values.prepareCleanClose(0L);
					values.requestDurableCleanupClose();
				}
				values.close();
				cleanup.finishSpool(spool ? values.durableCleanupClosedTransactionId() : -1L);
				closed = true;
			}
		}
	}

	private static class ClosingValueStore extends ValueStore implements AutoCloseable {
		ClosingValueStore(Path directory, LmdbStoreConfig config) throws IOException {
			super(new File(directory.toFile(), "values"), config);
			completeStoreInitialization(ids -> {
				// These tests own dictionary identity but do not create statements.
			});
		}
	}
